import { findings, applications, integrations, activities, riskFactors, navItems } from "./data.js";
import { icon, badge, statCard, panel, emptyState } from "./components.js";

const app = document.querySelector("#app");
const state = { page: "overview", search: "", filter: "All findings", appTier: "All tiers", weights: Object.fromEntries(riskFactors.map(f=>[f.label,f.weight])), toast: "", modal: null, authenticated: false, authView: "signin", authError: "" };
const esc = (s = "") => String(s).replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const date = new Intl.DateTimeFormat("en", { month: "short", day: "numeric", year: "numeric" }).format(new Date());

function shell() {
  if (!state.authenticated) { authScreen(); return; }
  app.innerHTML = `<aside class="sidebar"><a href="#overview" class="brand" data-page="overview"><span class="brand-mark"><svg viewBox="0 0 36 36" fill="none"><path d="M5 23.5 12.2 7l6.3 13.8L24 10l7 13.5H5Z" stroke="currentColor" stroke-width="2.6" stroke-linejoin="round"/><path d="M7 28h22" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"/></svg></span><span class="brand-name">Ri<span>View</span><small>SECURITY INTELLIGENCE</small></span></a>
    <button class="org-switch"><span class="org-avatar">N</span><span class="org-copy"><strong>Northstar Group</strong><small>Enterprise workspace</small></span><span class="chevron">⌄</span></button>
    <nav>${navItems.map(group => `<div class="nav-group"><div class="nav-label">${group.section}</div>${group.items.map(([id, symbol, label, count]) => `<button class="nav-item ${state.page === id ? "active" : ""}" data-page="${id}" aria-label="${label}" title="${label}">${icon(symbol)}<span>${label}</span>${count ? `<small class="nav-count">${count}</small>` : ""}</button>`).join("")}</div>`).join("")}</nav>
    <div class="sidebar-bottom"><div class="posture-mini"><div class="posture-mini-top"><span>Posture score</span><strong>72<span>/100</span></strong></div><div class="mini-track"><i></i></div><small>↑ 6 points this month</small></div><button class="nav-item" data-action="help">${icon("?")}<span>Help & support</span></button><button class="profile"><span class="profile-avatar">SP</span><span><strong>Sana Patel</strong><small>Security admin</small></span><span class="chevron">···</span></button></div></aside>
    <main class="main"><header class="topbar"><div class="breadcrumb"><span>Northstar Group</span><b>/</b><strong>${pageTitle(state.page)}</strong></div><div class="top-actions"><span class="updated"><i></i> Data updated ${date}</span><button class="icon-button" data-action="notifications" aria-label="Notifications">♧<i class="notification-dot"></i></button><div class="account-menu"><div class="account-identity"><span class="account-name"><strong>Admin RiView</strong><small>Security admin</small></span><span class="top-avatar">AR</span></div><button class="logout-link" data-action="logout" aria-label="Log out" title="Log out"><span aria-hidden="true">↪</span><span>Log out</span></button></div></div></header><div class="page-content">${renderPage()}</div><footer class="footer"><span>RiView <b>·</b> Security intelligence platform</span><span><i class="secure-dot"></i> All systems operational <b>·</b> Demo environment</span></footer></main>
    <div id="overlay"></div><div id="toast-region" aria-live="polite"></div>`;
  bind();
}

function authScreen() {
  const signup = state.authView === "signup";
  app.innerHTML = `<main class="auth-page"><section class="auth-story"><div class="auth-brand"><span class="brand-mark"><svg viewBox="0 0 36 36" fill="none"><path d="M5 23.5 12.2 7l6.3 13.8L24 10l7 13.5H5Z" stroke="currentColor" stroke-width="2.6" stroke-linejoin="round"/><path d="M7 28h22" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"/></svg></span><span class="brand-name">Ri<span>View</span></span></div><div class="auth-story-copy"><span class="auth-overline"><i></i> SECURITY INTELLIGENCE, IN CONTEXT</span><h1>See risk the way<br/>your business does.</h1><p>Bring vulnerabilities, threat activity, and business impact together. Know what matters, why it matters, and what to do next.</p><div class="auth-visual"><div class="visual-grid"></div><div class="visual-orbit orbit-one"></div><div class="visual-orbit orbit-two"></div><div class="visual-core"><span>R</span></div><div class="visual-node node-a"><i>◈</i><span>Exposure</span></div><div class="visual-node node-b"><i>◎</i><span>Threat</span></div><div class="visual-node node-c"><i>▣</i><span>Business</span></div><div class="visual-link link-a"></div><div class="visual-link link-b"></div><div class="visual-link link-c"></div><div class="visual-caption"><span class="visual-caption-dot"></span> Risk, connected.</div></div><div class="auth-story-foot"><span>BUSINESS-AWARE PRIORITIZATION</span><span>EXPLAINABLE BY DESIGN</span><span>BUILT FOR SECURITY TEAMS</span></div></div></section><section class="auth-side"><div class="auth-side-top"><span>Secure workspace access</span><span class="auth-status"><i></i> Systems operational</span></div><div class="auth-form-wrap"><div class="auth-mobile-brand"><span class="brand-mark"><svg viewBox="0 0 36 36" fill="none"><path d="M5 23.5 12.2 7l6.3 13.8L24 10l7 13.5H5Z" stroke="currentColor" stroke-width="2.6" stroke-linejoin="round"/><path d="M7 28h22" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"/></svg></span><span class="brand-name">Ri<span>View</span></span></div><div class="auth-heading"><span class="auth-kicker">${signup?"GET STARTED":"WELCOME BACK"}</span><h2>${signup?"Create your account":"Sign in to RiView"}</h2><p>${signup?"Start building a clearer view of your security risk.":"Enter your credentials to access your security workspace."}</p></div><form id="auth-form" class="auth-form" novalidate>${signup?`<label>Full name<input name="fullName" autocomplete="name" placeholder="Your name" required /></label><label>Work email<input name="email" type="email" autocomplete="email" placeholder="you@company.com" required /></label><label>Organization<input name="organization" autocomplete="organization" placeholder="Company name" required /></label><label>Password<input name="password" type="password" autocomplete="new-password" placeholder="Create a password" required /></label>`:`<label>Username<div class="auth-input-wrap"><span class="input-icon">♙</span><input name="username" autocomplete="username" value="Admin" required /></div></label><label>Password<div class="auth-input-wrap"><span class="input-icon">⌑</span><input name="password" type="password" autocomplete="current-password" value="Password123$" required /><button type="button" class="password-toggle" data-action="toggle-password" aria-label="Show password">◉</button></div></label><div class="auth-options"><label class="remember-option"><input type="checkbox" checked /> <span>Remember me</span></label><button type="button" class="auth-link" data-action="forgot-password">Forgot password?</button></div>`}${state.authError?`<div class="auth-error" role="alert">${state.authError}</div>`:""}<button class="btn-primary auth-submit" type="submit">${signup?"Create account":"Sign in"}<span>→</span></button></form>${!signup?`<div class="auth-divider"><span></span><small>OR CONTINUE WITH</small><span></span></div><button type="button" class="sso-button" data-action="sso"><span class="ms-logo"><i></i><i></i><i></i><i></i></span><span>Continue with Enterprise SSO</span><span class="sso-arrow">↗</span></button>`:""}<div class="auth-switch">${signup?"Already have an account?":"New to RiView?"} <button class="auth-link" data-action="toggle-auth">${signup?"Sign in":"Create an account"}</button></div><div class="auth-disclaimer">By continuing, you agree to the <a href="#terms" data-action="terms">Terms of Service</a> and <a href="#privacy" data-action="privacy">Privacy Policy</a>.</div></div><div class="auth-footer"><span>© 2026 RiView Security</span><span>Help center&nbsp;&nbsp; · &nbsp;&nbsp;Privacy</span></div></section></main>`;
  document.querySelector("#auth-form").addEventListener("submit", e=>{
    e.preventDefault();
    if(signup){toastAuth("Account request submitted. Check your work email to continue.");return;}
    const form=new FormData(e.currentTarget);
    if(form.get("username")==="Admin"&&form.get("password")==="Password123$"){state.authenticated=true;state.authError="";shell();return;}
    state.authError="Those credentials don't match this demo workspace. Try the prefilled demo login.";authScreen();
  });
  document.querySelectorAll("[data-action]").forEach(el=>el.addEventListener("click",()=>handleAction(el.dataset.action)));
}
function toastAuth(message){const node=document.createElement("div");node.className="auth-toast";node.textContent=message;document.querySelector(".auth-side").append(node);setTimeout(()=>node.remove(),3500);}
function pageTitle(page) { return ({ overview: "Overview", findings: "Findings", applications: "Applications", remediation: "Remediation", integrations: "Integrations", "risk-model": "Risk model" })[page] || "Overview"; }

function renderPage() {
  switch (state.page) {
    case "findings": return findingsPage();
    case "applications": return applicationsPage();
    case "integrations": return integrationsPage();
    case "risk-model": return riskPage();
    case "remediation": return remediationPage();
    default: return overviewPage();
  }
}

function pageHeading(kicker, title, copy, action = "") {
  return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${copy}</p></div><div class="heading-actions">${action}</div></div>`;
}
function btn(text, action, cls = "btn-secondary", symbol = "") { return `<button class="${cls}" data-action="${action}">${symbol ? `${icon(symbol)} ` : ""}${text}</button>`; }

function overviewPage() {
  const stats = [
    { label: "Open exposures", value: "1,284", delta: "8.2%", direction: "down", icon: "◈", tint: "violet", note: "vs. last month" },
    { label: "Critical risk", value: "37", delta: "12.5%", direction: "down", icon: "!", tint: "rose", note: "vs. last month" },
    { label: "KEV exposures", value: "12", delta: "4 resolved", direction: "down", icon: "⚑", tint: "amber", note: "this week" },
    { label: "SLA compliance", value: "86.4%", delta: "3.1%", direction: "up", icon: "◷", tint: "teal", note: "vs. last month" },
  ].map(statCard).join("");
  const riskContent = `<div class="risk-overview"><div class="score-wrap"><div class="score-ring"><div><strong>72</strong><small>of 100</small></div></div><span class="score-trend">↑ 6 pts</span></div><div class="risk-summary"><div class="risk-summary-head"><strong>Security posture</strong><span class="severity-pill">Needs attention</span></div><p>Your posture is improving. A small number of high-impact exposures drive most of your current risk.</p><div class="risk-statline"><span><i class="legend-dot dot-critical"></i>Critical <b>37</b></span><span><i class="legend-dot dot-high"></i>High <b>184</b></span><span><i class="legend-dot dot-medium"></i>Medium <b>623</b></span><span><i class="legend-dot dot-low"></i>Low <b>440</b></span></div></div><div class="risk-spark"><span>30-day trend</span><svg viewBox="0 0 170 50" preserveAspectRatio="none"><path d="M2 39 C18 38 17 26 34 30S50 33 62 24 77 29 92 17 111 26 122 14 140 20 151 8 162 10 168 4" fill="none" stroke="#4ed3b0" stroke-width="2.5" stroke-linecap="round"/><path d="M2 39 C18 38 17 26 34 30S50 33 62 24 77 29 92 17 111 26 122 14 140 20 151 8 162 10 168 4L168 50H2Z" fill="url(#sparkfill)"/><defs><linearGradient id="sparkfill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#4ed3b0" stop-opacity=".2"/><stop offset="1" stop-color="#4ed3b0" stop-opacity="0"/></linearGradient></defs></svg><small>↓ 8.2% since Sep 6</small></div></div>`;
  const exposureContent = `<div class="chart-meta"><div class="chart-legend"><span><i class="legend-dot dot-critical"></i>Critical</span><span><i class="legend-dot dot-high"></i>High</span><span><i class="legend-dot dot-medium"></i>Medium</span></div><span class="chart-range">Last 30 days <span>⌄</span></span></div><div class="bar-chart"><div class="chart-y"><span>1,500</span><span>1,000</span><span>500</span><span>0</span></div><div class="chart-area"><div class="gridline g1"></div><div class="gridline g2"></div><div class="gridline g3"></div><div class="gridline g4"></div><div class="bars">${[[65,51,36],[61,54,38],[63,49,36],[58,46,34],[56,42,32],[51,41,29],[49,38,27],[45,37,25],[43,35,24],[40,32,22],[36,29,20],[34,27,19]].map(a=>`<div class="bar-group"><i class="b-critical" style="height:${a[0]}%"></i><i class="b-high" style="height:${a[1]}%"></i><i class="b-medium" style="height:${a[2]}%"></i></div>`).join("")}</div><div class="chart-x"><span>Sep 6</span><span>Sep 13</span><span>Sep 20</span><span>Sep 27</span><span>Oct 6</span></div></div></div>`;
  const topApps = applications.slice(0, 4).map(a => `<div class="top-app-row"><span class="app-avatar ${a.color}">${a.name.split(" ").map(w=>w[0]).slice(0,2).join("")}</span><span class="top-app-name"><strong>${a.name}</strong><small>${a.tier.split(" · ")[0]}</small></span><span class="app-risk"><strong>${a.risk}</strong><small>risk</small></span><div class="mini-track app-track"><i style="width:${a.risk}%"></i></div></div>`).join("");
  const activity = activities.map(x=>`<div class="activity-row"><span class="activity-icon ${x.tone}">${x.icon}</span><div><strong>${x.text}</strong><small>${x.detail}</small></div><button class="dots" data-action="activity">···</button></div>`).join("");
  return `${pageHeading(`MONDAY, ${date.toUpperCase()}`, "Good morning, Admin", "Here’s what’s happening across your security posture today.", `${btn("Export report", "export", "btn-secondary", "↓")} ${btn("View priority queue", "page-findings", "btn-primary", "↗")}`)}
  <div class="stats-grid">${stats}</div>
  <div class="overview-grid"><div class="overview-left">${panel("Risk posture", "A consolidated view of your organization’s exposure.", riskContent)}${panel("Exposure trend", "Open findings by severity over time.", exposureContent, `<button class="text-action" data-action="page-findings">View findings ↗</button>`)}</div><div class="overview-right">${panel("Highest-risk applications", "Ranked by business-adjusted risk.", `<div class="top-app-list">${topApps}</div>`, `<button class="text-action" data-action="page-applications">View all</button>`)}${panel("Recent activity", "The latest changes in your workspace.", `<div class="activity-list">${activity}</div>`, `<button class="text-action" data-action="activity">View activity</button>`)}</div></div>
  <div class="insight-banner"><span class="insight-mark">✦</span><div><strong>Three exposures need your attention</strong><p>Known exploited vulnerabilities are affecting customer-facing systems. Review the priority queue to see recommended next steps.</p></div>${btn("Review exposures", "page-findings", "btn-insight")}</div>`;
}

function findingRows(rows) {
  if (!rows.length) return `<tr><td colspan="7">${emptyState("⌕", "No findings match", "Try another search or clear the selected filters.")}</td></tr>`;
  return rows.map(f=>`<tr class="click-row" data-finding="${f.id}"><td><div class="finding-title"><strong>${f.title}</strong><small>${f.id} <span>·</span> ${f.cve}</small></div></td><td><span class="asset-cell"><strong>${f.asset}</strong><small>${f.app}</small></span></td><td><span class="score ${f.cvss >= 9 ? "score-critical" : f.cvss >= 8 ? "score-high" : "score-medium"}">${f.cvss.toFixed(1)}</span></td><td>${f.kev ? `<span class="kev-tag">KEV</span> ` : ""}<span class="epss">${Math.round(f.epss*100)}%</span></td><td><span class="owner-cell"><span class="owner-avatar">${f.owner === "Unassigned" ? "—" : f.owner.split(" ").map(s=>s[0]).join("")}</span>${f.owner}</span></td><td>${badge(f.status, statusTone(f.status))}</td><td><span class="age-cell ${f.age > 30 ? "late" : ""}">${f.age}d</span></td></tr>`).join("");
}
function statusTone(s) { return ({"Open":"rose","In progress":"blue","Overdue":"amber","Exception":"slate"})[s] || "slate"; }

function findingsPage() {
  const rows = findings.filter(f => {
    const q = state.search.toLowerCase();
    return (!q || [f.title,f.cve,f.asset,f.app,f.id].some(x=>x.toLowerCase().includes(q))) && (state.filter === "All findings" || (state.filter === "Critical" && f.cvss >= 9) || (state.filter === "Known exploited" && f.kev) || f.status === state.filter);
  });
  const table = `<div class="table-scroll"><table class="data-table"><thead><tr><th>Vulnerability <span>↕</span></th><th>Affected asset <span>↕</span></th><th>CVSS <span>↕</span></th><th>Threat context <span>↕</span></th><th>Assigned to</th><th>Status</th><th>Age</th></tr></thead><tbody>${findingRows(rows)}</tbody></table></div>`;
  return `${pageHeading("EXPOSURE MANAGEMENT", "Findings", "Prioritize vulnerability exposure with live threat signals and business context.", `${btn("Export CSV", "export-findings", "btn-secondary", "↓")} ${btn("Sync sources", "sync", "btn-primary", "⟳")}`)}
  <div class="finding-kpis"><div><strong>1,284</strong><span>Open findings</span></div><div><strong class="text-rose">37</strong><span>Critical</span></div><div><strong class="text-amber">12</strong><span>Known exploited</span></div><div><strong>86.4%</strong><span>Within SLA</span></div></div>
  ${panel("Exposure queue", "Ranked by risk to your business, not severity alone.", `${`<div class="table-tools"><label class="search-box"><span>⌕</span><input id="finding-search" placeholder="Search vulnerabilities, assets..." value="${esc(state.search)}" /></label><select id="finding-filter" aria-label="Filter findings">${["All findings","Critical","Known exploited","Open","In progress","Overdue","Exception"].map(x=>`<option ${state.filter===x?"selected":""}>${x}</option>`).join("")}</select><span class="rows-count">${rows.length} findings</span><button class="icon-button subtle" data-action="filter-info">☷</button></div>`}${table}`, `<span class="live-label"><i></i> Live prioritization</span>`)}
  <div class="footnote"><span>ⓘ</span> Risk scores combine exploit probability, severity, exposure, business criticality and remediation status.</div>`;
}

function applicationsPage() {
  const cards = applications.filter(a=>state.appTier==="All tiers"||a.tier.split(" · ")[1]===state.appTier).map(a=>`<article class="application-card" data-app="${a.name}"><div class="application-card-head"><span class="app-avatar ${a.color}">${a.name.split(" ").map(w=>w[0]).slice(0,2).join("")}</span><button class="dots" data-action="app-menu">···</button></div><h3>${a.name}</h3><p>${a.owner}</p><div class="tier-line">${badge(a.tier.split(" · ")[1], a.risk >= 80 ? "rose" : "amber")}<span>${a.env}</span></div><div class="app-card-stats"><div><strong>${a.assets}</strong><small>Assets</small></div><div><strong>${a.findings}</strong><small>Open findings</small></div><div><strong>${a.risk}</strong><small>Risk score</small></div></div><div class="mini-track"><i style="width:${a.risk}%"></i></div><div class="application-link">View application <span>↗</span></div></article>`).join("");
  return `${pageHeading("BUSINESS CONTEXT", "Applications", "Connect technical exposure to the services and owners that matter.", `${btn("Import inventory", "import", "btn-secondary", "↑")} ${btn("Add application", "add-app", "btn-primary", "+")}`)}
  <div class="finding-kpis"><div><strong>64</strong><span>Applications</span></div><div><strong>1,992</strong><span>Assets mapped</span></div><div><strong>8</strong><span>Tier 1 critical</span></div><div><strong class="text-teal">92%</strong><span>Ownership coverage</span></div></div>
  <div class="application-toolbar"><label class="search-box"><span>⌕</span><input id="app-search" placeholder="Search applications..." /></label><select id="app-tier" aria-label="Filter applications by tier">${["All tiers","Critical","High"].map(x=>`<option ${state.appTier===x?"selected":""}>${x}</option>`).join("")}</select><span>Sorted by risk ↓</span></div><div class="application-grid">${cards}</div>`;
}

function integrationsPage() {
  const cards = integrations.map(i=>`<article class="integration-card"><div class="integration-top"><span class="integration-logo ${i.tint}">${i.icon}</span>${badge(i.state, i.state === "Connected" ? "teal" : i.state === "Action needed" ? "amber" : "slate")}</div><h3>${i.name}</h3><p>${i.category}</p><div class="integration-detail">${i.state === "Action needed" ? `<span class="detail-warning">●</span>` : `<span class="detail-dot">●</span>`} ${i.detail}</div>${i.records ? `<div class="integration-records">${i.records}</div>` : ""}<button class="integration-action" data-integration="${i.name}">${i.state === "Connected" ? "Manage connection" : i.state === "Action needed" ? "Review connection" : "Connect source"}<span>↗</span></button></article>`).join("");
  return `${pageHeading("DATA ECOSYSTEM", "Integrations", "Bring scanner, threat intelligence and business context together.", btn("Browse integrations", "browse-integrations", "btn-primary", "+"))}
  <div class="integration-summary"><div><span class="summary-icon">⟳</span><span><strong>5 sources connected</strong><small>Last successful sync 4 minutes ago</small></span></div><div class="integration-sync-status"><i></i> All syncs operational</div></div>
  <div class="section-heading"><div><h2>Your data sources</h2><p>Manage the systems that power your risk view.</p></div><select><option>All categories</option><option>Vulnerability management</option><option>Threat intelligence</option><option>Business context</option></select></div><div class="integration-grid">${cards}</div>
  <div class="integration-note"><span>ⓘ</span><div><strong>Built for your security ecosystem</strong><p>RiView correlates findings across your existing tools. Your scanner remains the system of record for technical discovery.</p></div><button class="text-action" data-action="architecture">View data flow ↗</button></div>`;
}

function riskPage() {
  const factors = riskFactors.map(f=>`<div class="factor-row"><span class="factor-dot ${f.color}"></span><div class="factor-info"><strong>${f.label}</strong><small>${f.desc}</small></div><div class="weight-control"><button aria-label="Decrease ${f.label} weighting" data-weight="${f.label}" data-delta="-5">−</button><strong>${state.weights[f.label]}%</strong><button aria-label="Increase ${f.label} weighting" data-weight="${f.label}" data-delta="5">+</button></div><div class="factor-meter"><i class="${f.color}" style="width:${state.weights[f.label]*3}%"></i></div></div>`).join("");
  const totalWeight = Object.values(state.weights).reduce((sum,w)=>sum+w,0);
  return `${pageHeading("TRANSPARENT BY DESIGN", "Risk model", "A business-aware prioritization model aligned to NIST guidance.", btn("Save changes", "save-model", "btn-primary", "✓"))}
  <div class="model-banner"><span class="model-shield">◉</span><div><strong>RiView Risk Score</strong><p>Combines vulnerability severity, threat activity, exposure and business context to surface the risks that need action first.</p></div><span class="version-chip">MODEL V1.2</span></div>
  <div class="risk-model-grid"><div>${panel("Scoring factors", "Adjust the weighting to reflect your organization's risk appetite.", `<div class="factors-list">${factors}</div><div class="weight-total"><span>Total weighting</span><strong id="weight-total" class="${totalWeight!==100?"text-rose":""}">${totalWeight}%</strong></div>`)}</div><div class="model-aside">${panel("Framework alignment", "Mapped to recognized security standards.", `<div class="framework-row"><span class="framework-icon nist">N</span><div><strong>NIST CSF 2.0</strong><small>Govern · Identify · Protect · Detect · Respond · Recover</small></div><span class="framework-check">✓</span></div><div class="framework-row"><span class="framework-icon sp">800</span><div><strong>NIST SP 800-30</strong><small>Risk assessment methodology</small></div><span class="framework-check">✓</span></div><div class="framework-row"><span class="framework-icon cisa">C</span><div><strong>CISA KEV & FIRST EPSS</strong><small>Threat likelihood signals</small></div><span class="framework-check">✓</span></div>`, `<button class="text-action" data-action="framework">View full mapping ↗</button>`)}${panel("Score interpretation", "How to read application-level risk.", `<div class="score-interpret"><div><span class="interpret-dot dot-critical"></span><strong>80–100</strong><small>Critical · Immediate action</small></div><div><span class="interpret-dot dot-high"></span><strong>60–79</strong><small>High · Prioritize this week</small></div><div><span class="interpret-dot dot-medium"></span><strong>30–59</strong><small>Moderate · Plan remediation</small></div><div><span class="interpret-dot dot-low"></span><strong>0–29</strong><small>Low · Monitor and maintain</small></div></div>`)}</div></div>
  <div class="footnote"><span>ⓘ</span> Model changes affect prioritization for all findings. Every score remains explainable at the finding level.</div>`;
}

function remediationPage() {
  const lanes = { "Needs triage": findings.filter(f=>f.status==="Open").slice(0,3), "In progress": findings.filter(f=>f.status==="In progress"), "Overdue": findings.filter(f=>f.status==="Overdue") };
  return `${pageHeading("CLOSE THE LOOP", "Remediation", "Move high-risk exposures to resolution with clear ownership and accountability.", btn("Create remediation plan", "create-plan", "btn-primary", "+"))}
  <div class="finding-kpis"><div><strong>48</strong><span>Due this week</span></div><div><strong class="text-rose">12</strong><span>Overdue</span></div><div><strong>86.4%</strong><span>Within SLA</span></div><div><strong>6.2d</strong><span>Avg. time to remediate</span></div></div><div class="board">${Object.entries(lanes).map(([name,items])=>`<section class="board-lane"><div class="lane-head"><strong>${name}</strong><span>${items.length}</span></div>${items.map(f=>`<button class="task-card" data-finding="${f.id}"><div class="task-tags">${badge(f.cvss>=9?"Critical":"High",f.cvss>=9?"rose":"amber")} ${f.kev?`<span class="kev-tag">KEV</span>`:""}</div><strong>${f.title}</strong><small>${f.cve} · ${f.app}</small><div class="task-foot"><span class="owner-avatar">${f.owner==="Unassigned"?"—":f.owner.split(" ").map(s=>s[0]).join("")}</span><span>${f.owner}</span><span class="task-due ${f.age>30?"late":""}">${f.age>30?"Overdue":"Due in 4d"}</span></div></button>`).join("")}</section>`).join("")}</div>`;
}

function findingModal(f) {
  return `<div class="modal-backdrop" data-action="close-modal"><section class="detail-modal" role="dialog" aria-modal="true" aria-label="Finding details" data-modal-content><div class="modal-head"><div><span class="eyebrow">VULNERABILITY DETAIL · ${f.id}</span><h2>${f.title}</h2><p>${f.cve} <span>·</span> Discovered by ${f.source}</p></div><button class="icon-button" data-action="close-modal">×</button></div><div class="modal-body"><div class="detail-kpis"><div><span>CVSS severity</span><strong class="text-rose">${f.cvss.toFixed(1)} <small>Critical</small></strong></div><div><span>Exploit probability</span><strong>${Math.round(f.epss*100)}%</strong></div><div><span>RiView risk score</span><strong class="text-rose">94 <small>Critical</small></strong></div></div><div class="detail-section"><h3>Business context</h3><div class="detail-context"><div><small>Affected asset</small><strong>${f.asset}</strong></div><div><small>Application</small><strong>${f.app}</strong></div><div><small>Business owner</small><strong>${f.team}</strong></div></div></div><div class="detail-section"><h3>Threat intelligence</h3><div class="threat-callout ${f.kev?"threat-danger":""}"><span>${f.kev?"⚑":"◎"}</span><div><strong>${f.kev?"Known exploited vulnerability":"No active exploitation observed"}</strong><small>${f.kev?"Listed in CISA KEV · Prioritize immediate remediation":"EPSS estimates likelihood of exploitation in the next 30 days"}</small></div></div></div><div class="detail-section"><h3>Remediation</h3><div class="detail-context"><div><small>Assigned to</small><strong>${f.owner}</strong></div><div><small>Finding status</small><strong>${f.status}</strong></div><div><small>Days open</small><strong>${f.age} days</strong></div></div></div></div><div class="modal-actions">${btn("Request exception", "request-exception", "btn-secondary")} ${btn("Create remediation ticket", "create-ticket", "btn-primary", "↗")}</div></section></div>`;
}

function bind() {
  document.querySelectorAll("[data-page]").forEach(el=>el.addEventListener("click",e=>{e.preventDefault();state.page=el.dataset.page;state.search="";shell();}));
  document.querySelectorAll("[data-action]").forEach(el=>el.addEventListener("click",()=>handleAction(el.dataset.action)));
  document.querySelectorAll("[data-finding]").forEach(el=>el.addEventListener("click",e=>{if(e.target.closest("button"))return;const f=findings.find(x=>x.id===el.dataset.finding);state.modal=f;document.querySelector("#overlay").innerHTML=findingModal(f);bindOverlay();}));
  const search=document.querySelector("#finding-search"); if(search) search.addEventListener("input",e=>{state.search=e.target.value;const pos=e.target.selectionStart; shell();const next=document.querySelector("#finding-search");next.focus();next.setSelectionRange(pos,pos);});
  const filter=document.querySelector("#finding-filter"); if(filter) filter.addEventListener("change",e=>{state.filter=e.target.value;shell();});
  document.querySelectorAll("[data-weight]").forEach(el=>el.addEventListener("click",()=>{
    const amount=Number(el.dataset.delta), name=el.dataset.weight, partner=name==="Operational urgency"?"Control effectiveness":"Operational urgency";
    if(state.weights[name]+amount<0||state.weights[partner]-amount<0)return;
    state.weights[name]+=amount;state.weights[partner]-=amount;shell();
  }));
  const appTier=document.querySelector("#app-tier");if(appTier)appTier.addEventListener("change",e=>{state.appTier=e.target.value;shell();});
  document.querySelectorAll("[data-integration]").forEach(el=>el.addEventListener("click",()=>toast(`${el.dataset.integration} connection setup is ready for configuration.`)));
  const appSearch=document.querySelector("#app-search"); if(appSearch) appSearch.addEventListener("input",()=>{const q=appSearch.value.toLowerCase();document.querySelectorAll(".application-card").forEach(card=>card.style.display=card.dataset.app.toLowerCase().includes(q)?"":"none");});
  document.querySelectorAll(".application-card").forEach(card=>card.addEventListener("click",e=>{if(!e.target.closest("button"))toast(`${card.dataset.app} application overview selected.`)}));
}
function bindOverlay() {document.querySelectorAll("#overlay [data-action]").forEach(el=>el.addEventListener("click",e=>{if(el.dataset.action==="close-modal"&&e.target.closest("[data-modal-content]")&&!e.target.closest("button[data-action='close-modal']"))return;handleAction(el.dataset.action);}));}
function handleAction(action) {
  if(action==="logout"){state.authenticated=false;state.page="overview";state.search="";state.filter="All findings";state.authView="signin";state.authError="";shell();return;}
  if(action==="toggle-auth"){state.authView=state.authView==="signup"?"signin":"signup";state.authError="";authScreen();return;}
  if(action==="toggle-password"){const input=document.querySelector('.auth-input-wrap input[name="password"]');const button=document.querySelector(".password-toggle");if(input){input.type=input.type==="password"?"text":"password";button?.setAttribute("aria-label",input.type==="password"?"Show password":"Hide password");}return;}
  if(action==="sso"){state.authenticated=true;state.authError="";shell();toast("Enterprise SSO demo session started.");return;}
  if(action==="forgot-password"){toastAuth("Password recovery is available in the connected product.");return;}
  if(action.startsWith("page-")){state.page=action.replace("page-","");state.search="";shell();return;}
  const messages={"export":"Your posture report is being prepared.","export-findings":"Findings export prepared for this demo.","sync":"Source sync started. Results will appear here when complete.","import":"Inventory import is ready for a CSV upload.","add-app":"Application setup is ready to configure.","browse-integrations":"Integration catalog opened.","filter-info":"Use search, severity, exploitation status or workflow status to narrow the queue.","help":"Help center opened.","notifications":"You’re all caught up.","activity":"Recent workspace activity.","app-menu":"Application actions opened.","architecture":"RiView correlates scanner findings with threat feeds, application inventory and workflow state.","framework":"NIST CSF 2.0 mapped across Govern, Identify, Protect, Detect, Respond and Recover.","create-plan":"Remediation plan draft created.","create-ticket":"Ticket draft created with finding context.","request-exception":"Exception request started. Business justification and approver are required.","close-modal":"","framework-map":"Framework alignment details opened."};
  if(action==="save-model"){if(Object.values(state.weights).reduce((s,w)=>s+w,0)!==100)return toast("Weights must total 100% before saving.");return toast("Risk model changes saved.");}
  if(action==="close-modal"){document.querySelector("#overlay").innerHTML="";state.modal=null;return;} toast(messages[action]||"This action is available in the connected product.");
}
function toast(message){const r=document.querySelector("#toast-region");if(!r)return;r.innerHTML=`<div class="toast"><span>✓</span>${message}</div>`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{r.innerHTML="";},3200);}
shell();
